std::vector<int64_t> Trajectory<PointType>::get_contained_lane_ids() const
{
  std::vector<int64_t> contained_lane_ids;
  const auto & [bases, values] = lane_ids_->get_data();

  for (size_t i = 0; i < bases.size(); i++) {
    if (start_ <= bases.at(i) && bases.at(i) <= end_) {
      for (const auto & lane_id : values.at(i)) {
        if (contained_lane_ids.empty()) {
          contained_lane_ids.emplace_back(lane_id);
        } else {
          int64_t last_lane_id = contained_lane_ids.back();

          if (last_lane_id != lane_id) {
            contained_lane_ids.emplace_back(lane_id);
          }
        }
      }
    }
  }
  return contained_lane_ids;
}

void BidirectionalTrafficModule::initialize_all_member_variables()
{
  bidirectional_lane_where_ego_was_ = std::nullopt;
  has_trajectory_bidirectional_lane_overlap_ = false;
  give_way_ = std::nullopt;
  oncoming_cars_ = std::nullopt;
}

get_bidirectional_lanelets_where_ego_is(
  const geometry_msgs::msg::Pose & ego_pose, const EgoParameters & ego_params,
  const std::vector<ConnectedBidirectionalLanelets::SharedConstPtr> & all_bidirectional_lanes)
{
  for (const auto & bidirectional_lane : all_bidirectional_lanes) {
    if (bidirectional_lane->is_object_on_this_lane(ego_pose, ego_params.ego_polygon(ego_pose))) {
      return bidirectional_lane;
    }
  }
  return std::nullopt;
}

bool ConnectedBidirectionalLanelets::is_object_on_this_lane(
  const geometry_msgs::msg::Pose & obj_pose,
  const autoware_utils_geometry::Polygon2d & obj_polygon) const
{
  Eigen::Vector2d obj_direction = calc_pose_direction(obj_pose);

  for (const auto & lanelet : bidirectional_lanelets_) {
    auto lanelet_polygon = lanelet.polygon2d().basicPolygon();
    if (boost::geometry::disjoint(obj_polygon, lanelet_polygon)) {
      continue;
    }
    Eigen::Vector2d lanelet_direction = calc_lanelet_direction(lanelet);
    if (is_same_direction(obj_direction, lanelet_direction)) {
      return true;
    }
  }
  return false;
}

Eigen::Vector2d calc_pose_direction(const geometry_msgs::msg::Pose & pose)
{
  double yaw = tf2::getYaw(pose.orientation);
  return {cos(yaw), sin(yaw)};
}

Eigen::Vector2d calc_lanelet_direction(const lanelet::ConstLanelet & lanelet)
{
  return (lanelet.centerline2d().back().basicPoint2d() -
          lanelet.centerline2d().front().basicPoint2d())
    .normalized();
}

bool is_same_direction(
  const Eigen::Vector2d & a, const Eigen::Vector2d & b, const double & eps = 1.0)
{
  return std::abs(a.dot(b) - 1) < eps;
}

[[nodiscard]] autoware_utils_geometry::Polygon2d EgoParameters::ego_polygon(
  const geometry_msgs::msg::Pose & ego_pose) const
{
  return autoware_utils_geometry::to_footprint(
    ego_pose, base_link2front, base_link2rear, vehicle_width);
}

Polygon2d to_footprint(
  const geometry_msgs::msg::Pose & base_link_pose, const double base_to_front,
  const double base_to_rear, const double width)
{
  using autoware_utils_geometry::calc_offset_pose;
  Polygon2d polygon;
  const auto point0 = calc_offset_pose(base_link_pose, base_to_front, width / 2.0, 0.0).position;
  const auto point1 = calc_offset_pose(base_link_pose, base_to_front, -width / 2.0, 0.0).position;
  const auto point2 = calc_offset_pose(base_link_pose, -base_to_rear, -width / 2.0, 0.0).position;
  const auto point3 = calc_offset_pose(base_link_pose, -base_to_rear, width / 2.0, 0.0).position;

  append_point_to_polygon(polygon, point0);
  append_point_to_polygon(polygon, point1);
  append_point_to_polygon(polygon, point2);
  append_point_to_polygon(polygon, point3);
  append_point_to_polygon(polygon, point0);

  return is_clockwise(polygon) ? polygon : inverse_clockwise(polygon);
}

void append_point_to_polygon(Polygon2d & polygon, const geometry_msgs::msg::Point & geom_point)
{
  Point2d point;
  point.x() = geom_point.x;
  point.y() = geom_point.y;

  bg::append(polygon.outer(), point);
}

bool is_clockwise(const Polygon2d & polygon)
{
  const int n = polygon.outer().size();
  const double x_offset = polygon.outer().at(0).x();
  const double y_offset = polygon.outer().at(0).y();
  double sum = 0.0;
  for (std::size_t i = 0; i < polygon.outer().size(); ++i) {
    sum +=
      (polygon.outer().at(i).x() - x_offset) * (polygon.outer().at((i + 1) % n).y() - y_offset) -
      (polygon.outer().at(i).y() - y_offset) * (polygon.outer().at((i + 1) % n).x() - x_offset);
  }

  return sum < 0.0;
}

Polygon2d inverse_clockwise(const Polygon2d & polygon)
{
  auto output_polygon = polygon;
  boost::geometry::reverse(output_polygon);
  return output_polygon;
}
